-- id=75  سعد بن معاذ
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 75;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'سعد بن معاذ بن النعمان بن امرئ القيس بن زيد بن عبد الأشهل بن جشم بن الحارث بن الخزرج بن النبيت واسمه عمرو بن مالك بن الأوس الأنصاري الأوسي ثم الأشهلي أبو عمرو وأمه كبشة بنت رافع لها صحبة أسلم على يد مصعب بن عمير لما أرسله النبي صلى الله عليه وسلم إلى المدينة يعلم المسلمين فلما أسلم قال لبني عبد الأشهل كلام رجالكم ونسائكم علي حرام حتى تسلموا فأسلموا فكان من أعظم الناس بركة في الإسلام وشهد بدرا لم يختلفوا فيه وشهد أحدا والخندق أخبرنا أبو جعفر عبيد الله بن أحمد بن السمين بإسناده إلى يونس بن بكير عن ابن إسحاق قال حدثني عبد الله بن سهل عن عائشة أنها كانت في حصن بني حارثة يوم الخندق وكانت أم سعد بن معاذ معها في الحصن وذلك قبل أن يضرب عليهن الحجاب وكان رسول الله صلى الله عليه وسلم وأصحابه حين خرجوا إلى الخندق قد رفعوا الذراري والنساء في الحصون مخافة عليهم من العدو قالت عائشة فمر سعد ابن معاذ عليه درع له مقلصة قد خرجت منها ذراعه وفي يده حربة وهو يقول

لبث قليلا يلحق الهيجا جمللا بأس بالموت إذا حان الأجل
فقالت أم سعد الحق يا بني قد والله أخرت فقالت عائشة يا أم سعد لوددت أن درع سعد أسبغ مما هي فخافت عليه حين أصيب السهم منه قال يونس عن ابن إسحاق قال فرماه فيما حدثني عاصم بن عمر بن قتادة حبان بن العرقة وهو من بني عامر بن لؤي فقطع أكحله فلما رماه قال خذها مني وأنا ابن العرقة فقال سعد عرق الله وجهك في النار اللهم إن كنت أبقيت من حرب قريش شيئا فأبقني لها فإنه لا قوم أحب إلي أن أجاهد من قوم آذوا رسولك وكذبوه وأخرجوه وإن كنت وضعت الحرب بيننا وبينهم فاجعله لي شهادة ولا تتمنى حتى تقر عيني في بني قريظة وهذا حبان بكسر الحاء وبالباء الموحدة وقيل غير ذلك وهذا أصح وهو ابن عبد مناف بن عمرو بن
معيص بن عامر بن لؤي وإنما قيل له ابن العرقة لأن أمه هي امرأة من بني سهم كانت طيبة الريح قال وحدثنا يونس عن ابن إسحاق قال حدثني من لا أتهم عن عبيد الله بن كعب بن مالك أنه كان يقول ما أصاب سعدا يومئذ بالسهم إلا أبو أسامة الجشمي حليف بني مخزوم قال وكان رسول الله صلى الله عليه وسلم حين أصاب سعدا السهم أمر أن يجعل في خيمة رفيدة الأسلمية في المسجد ليعوده من قريب فلما حضر رسول الله صلى الله عليه وسلم قريظة وأذعنوا أن ينزلوا على حكم سعد بن معاذ أخبرنا عبد الله بن أحمد بن عبد القاهر الخطيب بإسناده إلى أبي داود الطيالسي أخبرنا شعبة عن سعد بن إبراهيم قال سمعت أبا أمامة بن سهل بن حنيف يحدث عن أبي سعيد الخدري قال لما أرسل رسول الله صلى الله عليه وسلم إلى سعد بن معاذ ليحضر يحكم في قريظة فأقبل على حمار فلما دنا من النبي صلى الله عليه وسلم قال قوموا إلى سيدكم أو قال خيركم احكم فيهم قال إني أحكم فيهم أن تقتل مقاتلتهم وتسبي ذراريهم فقال رسول الله صلى الله عليه وسلم حكمت بحكم الملك وأخبرنا أبو جعفر بإسناده عن يونس بن بكير عن ابن إسحاق قال فقاموا إليه فقالوا يا أبا عمر وقد ولاك رسول الله صلى الله عليه وسلم أمر مواليك لتحكم فيهم فقال سعد عليكم بذلك عهد الله وميثاقه قالوا نعم قال وعلى من هاهنا من الناحية التي فيها رسول الله صلى الله عليه وسلم ومن معه وهو معرض عن رسول الله صلى الله عليه وسلم إجلالا له فقال رسول الله صلى الله عليه وسلم نعم فقال سعد أحكم أن تقتل الرجال وتقسم الأموال وتسبى الذراري أخبرنا أبو البركات الحسن بن محمد بن هبة الله الدمشقي أخبرنا أبو العشائر محمد بن الخليل بن فارس القيسي أخبرنا أبو القاسم علي بن محمد بن علي بن أبي العلاء أخبرنا أبو محمد عبد الرحمن بن عثمان بن أبي نصر أخبرنا أبو إسحاق إبراهيم بن محمد بن أحمد بن أبي ثابت قال حدثنا يزيد بن محمد بن عبد الصمد أخبرنا عبد الله بن أبي يزيد أخبرنا صدقة عن عياض بن عبد الرحمن عن سعد بن إبراهيم عن أبيه عن جده قال كنا جلوسا عند رسول الله صلى الله عليه وسلم فجاء سعد ابن معاذ فقال هذا سيدكم وكان سعد لما جرح ودعا بما تقدم ذكره انقطع الدم فلما حكم في قريظة انفجر عرقه وكان رسول الله صلى الله عليه وسلم يعوده وأبو بكر وعمر والمسلمون قالت عائشة فوالذي نفسي بيده إني لأعرف بكاء أبي بكر من بكاء عمر وقال عمرو بن شرحبيل أن سعد بن معاذ لما انفجر جرحه احتضنه رسول الله صلى الله عليه وسلم فجعلت الدماء تسيل على رسول الله فجاء أبو بكر فقال وا انكسار ظهراه فقال له النبي صلى الله عليه وسلم مه فقال عمر إنا لله وإنا إليه راجعون روى أن جبريل عليه السلام نزل إلى النبي صلى الله عليه وسلم معتجرا بعمامة من إستبرق فقال يا نبي الله من هذا الذي فتحت له أبواب السماء واهتز له العرش فخرج رسول الله صلى الله عليه وسلم سريعا يجر ثوبه فوجد سعدا قد قبض ولما دفنه رسول الله صلى الله عليه وسلم وانصرف من جنازته جعلت دموعه تحادر على لحيته ويده في لحيته وندبته أمه فقالت

ويل أم سعد سعدابراعة ونجداويل أم سعد سعداصرامة وجدا
فقال النبي صلى الله عليه وسلم كل نادبة كاذبة إلا نادبة سعد أخبرنا أبو الفضل عبد الله بن أحمد الطوسي أخبرنا نصر بن أحمد بن عبد الله بن البطر إجازة إن لم يكن سماعا أخبرنا أبو علي بن شاذان أخبرنا عثمان بن أحمد الدقاق أخبرنا عبد الملك بن محمد أبو قلابة الرقاشي أخبرنا أبو ربيعة أخبرنا أبو عوانة عن الأعمش عن أبي سفيان عن جابر بن عبد الله قال سمعت رسول الله صلى الله عليه وسلم يقول اهتز عرش الرحمن لموت سعد بن معاذ قال الأعمش وحدثنا أبو صالح عن جابر عن النبي صلى الله عليه وسلم فقيل لجابر إن البراء يقول اهتز السرير فقال جابر إنه كان بين هذين الحيين الأوس والخزرج ضغائن سمعت رسول الله صلى الله عليه وسلم يقول اهتز عرش الرحمن لموت سعد بن معاذ أخبرنا إسماعيل بن عبيد الله وغير واحد بإسنادهم إلى أبي عيسى الترمذي قال حدثنا محمود بن غيلان أخبرنا وكيع عن سفيان عن أبي إسحاق عن البراء قال أهدي لرسول الله صلى الله عليه وسلم ثوب حرير فجعلوا يعجبون من لينه فقال رسول الله صلى الله عليه وسلم أتعجبون من هذا لمناديل سعد في الجنة أحسن من هذا قال وأخبرنا الترمذي أخبرنا عبد بن حميد أخبرنا عبد الرزاق أخبرنا معمر عن قتادة عن أنس قال لما حملت جنازة سعد بن معاذ قال المنافقون ما أخف جنازته وذلك لحكمه في بني قريظة فبلغ ذلك النبي صلى الله عليه وسلم فقال إن الملائكة كانت تحمله وقال سعد بن أبي وقاص عن النبي صلى الله عليه وسلم أنه قال لقد نزل من الملائكة في جنازة سعد بن معاذ سبعون ألفا ما وطؤوا الأرض قبل وبحق أعطاه الله تعالى ذلك ومقاماته في الاسلام مشهورة 
كبيرة ولو لم يكن له إلا يوم بدر فإن النبي الله صلى الله عليه وسلم لما سار إلى بدر وأتاه خبر نفير قريش استشار الناس فقال المقداد فأحسن وكذلك أبو بكر وعمر وكان رسول الله صلى الله عليه وسلم يريد الأنصار لأنهم عدد الناس فقال سعد بن معاذ والله لكأنك تريدنا يا رسول الله قال أجل قال سعد فقد آمنا بك وصدقناك وشهدنا أن ما جئت به الحق وأعطيناك مواثيقنا على السمع والطاعة فامض يا رسول الله لما أردت فنحن معك فوالذي بعثك بالحق لو استعرضت بنا هذا البحر لخضناه معك ما تخلف منا رجل واحد وما نكره أن تلقى بنا عدونا غدا إنا لصبر عند الحرب صدق عند اللقاء لعل الله يريك فينا ما تقر به عينك فسر بنا على بركة الله فسر رسول الله صلى الله عليه وسلم لقوله ونشطه ذلك للقاء الكفار فكان ما هو مشهور وكفي به فخرا دع ما سواه'
WHERE id = 75
  AND content_ar LIKE '(ب د ع) سعد بن معاذ %'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 75;

-- id=76  سعد بن عبادة
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 76;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'سعد بن عبادة بن دليم بن حارثة بن أبي حزيمة وقيل حارثة بن حزام بن حزيمة بن ثعلبة بن طريف بن الخزرج بن ساعدة بن كعب بن الخزرج الأنصاري الساعدي يكنى أبا ثابت وقيل أبا قيس والأول أصح وكان نقيب بني ساعدة عند جميعهم وشهد بدرا عند بعضهم ولم يذكره ابن عقبة ولا ابن إسحاق في البدريين وذكره فيهم الواقدي والمدائني وابن الكلبي وكان سيدا جوادا وهو صاحب راية الأنصار في المشاهد كلها وكان وجيها في الأنصار ذا رياسة وسيادة يعترف قومه له بها وكان يحمل إلى النبي صلى الله عليه وسلم كل يوم جفنة مملؤة ثريد أو لحما تدور معه حيث دار يقال لم يكن في الأوس ولا في الخزرج أربعة مطعمون يتوالون في بيت واحد إلا قيس ابن سعد بن عبادة بن دليم وله ولأهله في الجود أخبار حسنة أخبرنا أبو أحمد عبد الوهاب بن أبي منصور الأمين بإسناده إلى أبي داود سليمان بن الأشعث قال حدثنا محمد بن المثنى وهشام بن مروان المعنى قال ابن المثنى أخبرنا الوليد بن مسلم أخبرنا الأوزاعي قال سمعت يحيى بن أبي كثير يقول حدثني محمد بن عبد الرحمن بن أسعد ابن زرارة عن قيس بن سعد قال زارنا رسول الله صلى الله عليه وسلم في منزلنا فقال السلام عليكم ورحمة الله قال فرد سعد ردا خفيا قال قيس فقلت ألا تأذن لرسول الله صلى الله عليه وسلم قال دعه يكثر علينا من السلام فقال رسول الله السلام ثم رجع رسول الله واتبعه سعد فقال يا رسول الله إني كنت أسمع تسليمك وأرد عليك ردا خفيا لتكثر علينا من السلام فانصرف معه رسول الله فأمر له سعد بغسل فاغتسل ثم ناوله ملحفة مصبوغة بزعفران أو ورس فاشتمل بها ثم رفع رسول الله يديه وهو يقول اللهم اجعل صلواتك ورحمتك على آل سعد بن عبادة وقد كان قيس بن سعد من أعظم الناس جودا وكرما وقال رسول الله صلى الله عليه وسلم عن قيس بن سعد بن عبادة إنه من بيت جود وفي سعد بن عبادة وسعد بن معاذ جاء الخبر أن قريشا سمعوا صائحا يصيح ليلا على أبي قبيس

فإن يسلم السعدان يصبح محمدبمكة لا يخشى خلاف مخالف
قال فظنت قريش أنه يعني سعد بن زيد مناة بن تميم وسعد هذيم من قضاعة فسمعوا الليلة الثانية قائلا

أيا سعد سعد الأوس كن أنت ناصراويا سعد سعد الخزرجيين الغطارفأجيبا إلى داعي الهدى وتمنياعلى الله في الفردوس منية عارفوإن ثواب الله للطالب الهدىجنان من الفردوس ذات زخارف
فقالوا هذا سعد بن معاذ وسعد بن عبادة ولما كان غزوة الخندق بذل رسول الله صلى الله عليه وسلم لعيينة بن حصن ثلث ثمار المدينة لينصرف بمن معه من غطفان واستشار سعد بن معاذ وسعد بن عبادة دون سائر الناس فقالا يا رسول الله إن كنت أمرت بشئ فافعله وإن كان غير ذلك فوالله ما نعطيهم إلا السيف فقال رسول الله لم أومر بشئ وإنما هو رأي أعرضه عليكما فقالا يا رسول الله ما طمعوا بذلك منا قط في الجاهلية فكيف اليوم وقد هدانا الله بك فسر النبي صلى الله عليه وسلم بقولهما وكانت راية رسول الله صلى الله عليه وسلم بيد سعد بن عبادة يوم الفتح فمر بها على أبي سفيان وكان أبو سفيان قد أسلم فقال له سعد اليوم يوم الملحمة اليوم تستحل الحرمة اليوم أذل الله قريشا فلما مر رسول الله في كتيبة من الأنصار ناداه أبو سفيان يا رسول الله أمر ت بقتل قومك زعم سعد أنه قاتلنا وقال عثمان وعبد الرحمن بن عوف يا رسول الله ما نأمن من سعدا أن تكون منه صولة في قريش فقال رسول الله يا أبا سفيان اليوم يوم المرحمة اليوم أعز الله قريشا فأخذ رسول الله اللواء من سعد وأعطاه ابنه قيسا وقيل أعطى اللواء الزبير بن العوام وقيل أمر عليا فأخذ اللواء ودخل به مكة وكان غيورا شديد الغيرة وإياه أراد رسول الله بقوله ان سعد الغيور وإني لأغير من سعد والله أغير منا وغيرة الله أن تؤتي محارمه وفي هذا الحديث قصة ولما توفي النبي صلى الله عليه وسلم طمع في الخلافة وجلس في سقيفة بني ساعدة ليبايع لنفسه فجاء إليه أبو بكر وعمر فبايع الناس أبا بكر وعدلوا عن سعد فلم يبايع سعد أبا بكر ولا عمر وسار إلى الشام فأقام به بحوران إلى أن مات سنة خمس عشرة وقيل سنة أربع عشرة وقيل مات سنة إحدى عشرة ولم يختلفوا أنه وجد ميتا على مغتسله وقد اخضر جسده ولم يشعروا بموته بالمدينة حتى سمعوا قائلا يقول من بئر ولا يرون أحدا 

نحن قتلنا سيد الخزرج سعد بن عبادةفرميناه بسهمين فلم نخط فؤاده
فلما سمع الغلمان ذلك ذعروا فحفظ ذلك اليوم فوجدوه اليوم الذي مات فيه سعد بالشام قيل إن البئر التي سمع منها الصوت بئر منبه وقيل بئر سكن قال ابن سيرين بينا سعد يبول قائما إذ اتكأ فمات قتلته الجن وقال البيتين قيل إن قبره بالمنيحة قرية من غوطة دمشق وهو مشهور يزار إلى اليوم روى عنه ابن عباس وغيره من حديثه أن النبي صلى الله عليه وسلم قال ما من رجل تعلم القرآن ثم نسيه إلا لقي الله وهو أجذم وما من أمير عشرة إلا أتى يوم القيامة مغلولا حتى يطلقه العدل أخرجه الثلاثة * خزيمة بفتح الحاء المهملة وكسر الزاي وبعدها ياء تحتها نقطتان ثم ميم وهاء'
WHERE id = 76
  AND content_ar LIKE '(ب د ع) سعد بن عبادة%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 76;

